      await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body1), headers: { 'Content-Type': 'application/json' } })

      await new Promise(r => setTimeout(r, 10))

      const body2 = { paymentMethod: 'card', lineItems: [{ lineType: 'part', partId: 'p2', quantity: 1, unitPriceNet: 3000, vatRateId: 'vat-standard', description: 'Chain Ring 50T' }] }
      await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body2), headers: { 'Content-Type': 'application/json' } })

      const res = await app.request('/api/sales')

      expect(res.status).toBe(200)
      const json = await res.json() as SalesListResponse
      expect(json.sales).toHaveLength(2)
      expect(json.total).toBe(2)

      // Verify newest first ordering (second sale should be first in list)
      expect((json.sales[0] as Record<string, string>).saleNumber).toBe('SA-0002')
      expect((json.sales[1] as Record<string, string>).saleNumber).toBe('SA-0001')
    })

    it('should respect limit query parameter', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 },
        { id: 'p2', barcode: 'BAR-002', name: 'Chain Ring 50T', priceNet: 3000 }
      ])
      await db.insert(stockMovements).values([
        { id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' },
        { id: 'm2', partId: 'p2', quantityDelta: 5, reason: 'manual_correction' }
      ])

      // Create two sales
      const body1 = { paymentMethod: 'cash', lineItems: [{ lineType: 'part', partId: 'p1', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' }] }
      await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body1), headers: { 'Content-Type': 'application/json' } })

      const body2 = { paymentMethod: 'card', lineItems: [{ lineType: 'part', partId: 'p2', quantity: 1, unitPriceNet: 3000, vatRateId: 'vat-standard', description: 'Chain Ring 50T' }] }
      await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body2), headers: { 'Content-Type': 'application/json' } })

      const res = await app.request('/api/sales?limit=1')

      expect(res.status).toBe(200)
      const json = await res.json() as SalesListResponse
      // Limit applies to returned array but total should still be 2
      expect(json.sales).toHaveLength(1)
      expect(json.total).toBe(2)
    })
  })

  // ---------------------------------------------------------------------------
  // GET /api/sales/:id — Get a single sale with full details
  // ---------------------------------------------------------------------------
  describe('GET /api/sales/:id', () => {
    it('should return 404 for non-existent sale', async () => {
      const res = await app.request('/api/sales/nonexistent-id')

      expect(res.status).toBe(404)
      const json = await res.json() as VoidErrorResponse
      expect(json.code).toBe('NOT_FOUND')
    })

    it('should return full sale details including lines, payments, and stock movements', async () => {
      // Seed data
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 }
      ])
      await db.insert(stockMovements).values({ id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' })

      // Create a sale
      const body = { paymentMethod: 'cash', lineItems: [{ lineType: 'part', partId: 'p1', quantity: 2, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' }] }
      const createRes = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as SaleResponse
      const saleId = (createJson.sale as Record<string, unknown>).id as string

      // Fetch the sale detail
      const res = await app.request(`/api/sales/${saleId}`)

      expect(res.status).toBe(200)
      const json = await res.json() as SaleDetailResponse
      expect((json.sale as Record<string, unknown>).id).toBe(saleId)
      expect(json.lineItems).toHaveLength(1)
      expect(json.payments).toHaveLength(1)
      expect(json.stockMovements).toHaveLength(1)

      // Verify stock movement is negative (deduction)
      const movement = json.stockMovements[0] as Record<string, unknown>
      expect(movement.quantityDelta).toBe(-2)
    })
  })

  // ---------------------------------------------------------------------------
  // PATCH /api/sales/:id/void — Void a completed sale
  // ---------------------------------------------------------------------------
  describe('PATCH /api/sales/:id/void', () => {
    it('should void a completed sale and return updated status', async () => {
      // Seed data
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 }
      ])
      await db.insert(stockMovements).values({ id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' })

      // Create a sale first
      const body = { paymentMethod: 'cash', lineItems: [{ lineType: 'part', partId: 'p1', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' }] }
      const createRes = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as SaleResponse
      const saleId = (createJson.sale as Record<string, unknown>).id as string

      // Void the sale
      const res = await app.request(`/api/sales/${saleId}/void`, { method: 'PATCH' })

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      expect((json.sale as Record<string, unknown>).status).toBe('voided')
    })

    it('should return 404 for non-existent sale', async () => {
      const res = await app.request('/api/sales/nonexistent-id/void', { method: 'PATCH' })

      expect(res.status).toBe(404)
      const json = await res.json() as VoidErrorResponse
      expect(json.code).toBe('NOT_FOUND')
    })

    it('should return 409 when trying to void an already-voided sale', async () => {
      // Seed data
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 }
      ])
      await db.insert(stockMovements).values({ id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' })

      // Create and void a sale
      const body = { paymentMethod: 'cash', lineItems: [{ lineType: 'part', partId: 'p1', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' }] }
      const createRes = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as SaleResponse
      const saleId = (createJson.sale as Record<string, unknown>).id as string

      // First void — should succeed
      const res1 = await app.request(`/api/sales/${saleId}/void`, { method: 'PATCH' })
      expect(res1.status).toBe(200)

      // Second void — should fail with 409
      const res2 = await app.request(`/api/sales/${saleId}/void`, { method: 'PATCH' })

      expect(res2.status).toBe(409)
      const json = await res2.json() as VoidErrorResponse
      expect(json.code).toBe('ALREADY_VOIDED')
    })

    it('should only change sale status — no stock movement or payment side effects (R13)', async () => {
      // Seed data
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 }
      ])
      await db.insert(stockMovements).values({ id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' })

      // Create a sale with two line items
      const body = {
        paymentMethod: 'cash',
        lineItems: [
          { lineType: 'part', partId: 'p1', quantity: 2, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' }
        ]
      }
      const createRes = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as SaleResponse
      const saleId = (createJson.sale as Record<string, unknown>).id as string

      // Capture pre-void state
      const preMovementsCount = (await db.select({ count: drizzleCount() }).from(stockMovements).where(eq(stockMovements.referenceType, 'sale')))[0].count
      const prePaymentsCount = (await db.select({ count: drizzleCount() }).from(payments))[0].count
      const preAllocationsCount = (await db.select({ count: drizzleCount() }).from(paymentAllocations))[0].count

      // Void the sale
      const res = await app.request(`/api/sales/${saleId}/void`, { method: 'PATCH' })
      expect(res.status).toBe(200)

      // Verify only status changed — no new stock movements, payments, or allocations
      const postMovementsCount = (await db.select({ count: drizzleCount() }).from(stockMovements).where(eq(stockMovements.referenceType, 'sale')))[0].count
      const postPaymentsCount = (await db.select({ count: drizzleCount() }).from(payments))[0].count
      const postAllocationsCount = (await db.select({ count: drizzleCount() }).from(paymentAllocations))[0].count

      expect(postMovementsCount).toBe(preMovementsCount)
      expect(postPaymentsCount).toBe(prePaymentsCount)
      expect(postAllocationsCount).toBe(preAllocationsCount)

      // Verify sale status is voided but other fields unchanged
      const json = await res.json() as Record<string, unknown>
      expect((json.sale as Record<string, unknown>).status).toBe('voided')
    })
  })
})

import { describe, it, expect } from 'vitest'
import {
  paymentMethodSchema,
  cartLineItemSchema,
  createDirectSaleInputSchema,
} from './sales.js'

// ── Payment Method ────────────────────────────────────────────────

describe('paymentMethodSchema', () => {
  it('accepts "cash"', () => {
    const result = paymentMethodSchema.safeParse('cash')
    expect(result.success).toBe(true)
    if (result.success) expect(result.data).toBe('cash')
  })

  it('accepts "card"', () => {
    const result = paymentMethodSchema.safeParse('card')
    expect(result.success).toBe(true)
    if (result.success) expect(result.data).toBe('card')
  })

  it('rejects invalid payment method', () => {
    const result = paymentMethodSchema.safeParse('bank_transfer')
    expect(result.success).toBe(false)
  })

  it('rejects empty string', () => {
    const result = paymentMethodSchema.safeParse('')
    expect(result.success).toBe(false)
  })

  it('rejects null', () => {
    const result = paymentMethodSchema.safeParse(null as unknown as 'cash' | 'card')
    expect(result.success).toBe(false)
  })
})

// ── Cart Line Item (discriminated union: part / labor / bicycle) ──

describe('cartLineItemSchema', () => {
  const validPart = {
    lineType: 'part' as const,
